import * as THREE from 'three';

import { Solution } from '../';
import { ThreeCore } from '../ThreeCore';
import { AppCommon } from './AppCommon';
import { ActiveCommand } from './ActiveCommand';

import { Hypercube } from './HyperCube';
import { Substation } from './Substation';

import { getGround, getGroundBasic, createStudioEnvironment } from '../Utils';
import { CLICK_TYPE } from '../Utils/const';

export class AppCore {
	public solution: Solution;
	public threeCore: ThreeCore;
	public common: AppCommon;
	public activeCommand: ActiveCommand;

	public scene: THREE.Scene;
	public hyperCube: Hypercube;
	public substation: Substation;

	public boxMeshes: THREE.Mesh[] = [];
	public meshDoorLeft: THREE.Mesh = undefined;
	public meshDoorRight: THREE.Mesh = undefined;

	public meshGround: THREE.Mesh = undefined;
	public meshSphere: THREE.Mesh = undefined;
	public meshFloor: THREE.Mesh = undefined;

	constructor(solution: Solution, sphereNeeded = false) {
		this.solution = solution;
		this.threeCore = solution.threeCore;
		this.scene = solution.threeCore.scene;
		this.common = new AppCommon(this);
		this.activeCommand = new ActiveCommand(this);
		this.solution.threeCore.readyBinding = () => {
			return this.ready;
		};
		this.init();
	}
	public async init() {
		this.meshGround = getGround(this.threeCore.scene, this.threeCore.renderer);
		// this.scene.add(this.meshGround);
		// this.threeCore.groundReflector = this.meshGround;

		this.meshFloor = getGroundBasic(-18);
		this.scene.add(this.meshFloor);

		this.meshSphere = createStudioEnvironment();
		this.scene.add(this.meshSphere);

		this.hyperCube = new Hypercube(this);
		this.substation = new Substation(this);
	}
	// public initPost(fn: () => void) {
	// 	this.activeCommand.bindMouseEvent(fn);
	// }
	public get ready() {
		if (this.substation.ready && this.hyperCube.ready) {
			return true;
		} else {
			return false;
		}
	}
	public update() {
		this.hyperCube.update();
	}
	public onMouseEventListener(e: MouseEvent, type: CLICK_TYPE) {
		this.activeCommand.onMouseEventListener(e, type);
	}

	public destroy() {}
	public showStudioEnv(v) {
		this.meshGround.visible = v;
		this.meshSphere.visible = v;
		this.meshFloor.visible = v;
	}
}
